-- ==========================================
-- SUPABASE POSTGRESQL DATABASE SCHEMA
-- STT DATA COLLECTION & EVALUATION PLATFORM
-- ==========================================

-- Enable UUID extension if not already enabled
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Table: auth_tokens
-- Manages access tokens generated by Admin for Students and Evaluators.
CREATE TABLE IF NOT EXISTS auth_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    token TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('student', 'evaluator')),
    label TEXT, -- Helper metadata to know who the token is generated for
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Table: sample_text
-- Stores target pronunciation words/phrases for students to read.
CREATE TABLE IF NOT EXISTS sample_text (
    id SERIAL PRIMARY KEY,
    text TEXT NOT NULL UNIQUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Table: audio_records
-- Stores student recordings submitted via the recorder page.
CREATE TABLE IF NOT EXISTS audio_records (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    word_text TEXT NOT NULL, -- Target Vietnamese word that was read
    audio_url TEXT NOT NULL,  -- URL to the audio file stored in Supabase storage bucket 'audios'
    student_token TEXT NOT NULL, -- The token used to record this audio
    status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'declined')) DEFAULT 'pending',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 4. Table: transcripts
-- Stores speech predictions (from models) and human guesses (from evaluators) for approved audio.
-- Using a one-to-many relationship mapping audio_records to transcripts to support multiple evaluators!
CREATE TABLE IF NOT EXISTS transcripts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    audio_record_id UUID NOT NULL REFERENCES audio_records(id) ON DELETE CASCADE,
    source TEXT NOT NULL, -- e.g. 'model:moonshine_base_vi_quantized', 'model:zipformer_vi_2025_04_20', 'evaluator:EVAL-123'
    transcript_text TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

