-- Disable Row Level Security (RLS) on all tables to allow public client-side inserts
ALTER TABLE auth_tokens DISABLE ROW LEVEL SECURITY;
ALTER TABLE sample_text DISABLE ROW LEVEL SECURITY;
ALTER TABLE audio_records DISABLE ROW LEVEL SECURITY;
ALTER TABLE transcripts DISABLE ROW LEVEL SECURITY;
